?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Mahameru — EC/OC Order</title><link rel="stylesheet" href="assets/app.css"></head><body><main class="container"><header class="topbar"><div><div class="brand">MAHAMERU</div><div class="muted">EC / OC Order</div></div><a class="button" href="sales.php">Sales</a></header><section class="card"><h2>Order Aktif</h2><div id="visitState" class="muted">Memeriksa Visit aktif...</div><label>Tipe Order<select id="orderType"><option value="EC">EC</option><option value="OC">OC</option></select></label><label>Product ID<input id="productId" type="number" min="1" required></label><label>Qty<input id="qty" type="number" min="0.01" step="0.01" required></label><label>Discount %<input id="discount" type="number" min="0" max="100" step="0.01" value="0"></label><label>Catatan<textarea id="notes"></textarea></label><button class="primary" id="submit" disabled>Buat Order</button><pre id="result"></pre></section></main><script>const csrf=<?=json_encode($csrf)?>;let activeVisit=null;const state=document.querySelector('#visitState'),submit=document.querySelector('#submit'),result=document.querySelector('#result');async function loadVisit(){try{const r=await fetch('../api/visit.php?action=active',{credentials:'same-origin'});const d=await r.json();activeVisit=d.success?d.visit:null;if(activeVisit){state.textContent='Visit aktif: '+(activeVisit.outlet_name||activeVisit.outlet_code||activeVisit.outlet_id);submit.disabled=false;}else{state.textContent='Tidak ada Visit aktif. Check-In terlebih dahulu.';submit.disabled=true;}}catch(e){state.textContent='Gagal membaca status Visit.';submit.disabled=true;}}submit.onclick=async()=>{if(!activeVisit){return;}submit.disabled=true;result.textContent='Memproses...';try{const r=await fetch('../api/orders.php',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':csrf},credentials:'same-origin',body:JSON.stringify({visit_id:Number(activeVisit.id),order_type:document.querySelector('#orderType').value,items:[{product_id:Number(document.querySelector('#productId').value),qty:Number(document.querySelector('#qty').value),discount_percent:Number(document.querySelector('#discount').value)}],notes:document.querySelector('#notes').value})});result.textContent=await r.text();}catch(e){result.textContent='Order gagal: '+e.message;}finally{await loadVisit();submit.disabled=!activeVisit;}};loadVisit();</script></body></html>
